public without sharing class OpportunityPipelineHandler {

    public static void handle(
        System.TriggerOperation operation,
        List<Opportunity> oldList,
        List<Opportunity> newList,
        Map<Id, Opportunity> oldMap
    ) {
        Set<Id> accountIds = new Set<Id>();

        if (operation == System.TriggerOperation.AFTER_INSERT
            || operation == System.TriggerOperation.AFTER_UNDELETE) {
            for (Opportunity o : newList) {
                addId(accountIds, o.AccountId);
            }
        } else if (operation == System.TriggerOperation.AFTER_DELETE) {
            for (Opportunity o : oldList) {
                addId(accountIds, o.AccountId);
            }
        } else if (operation == System.TriggerOperation.AFTER_UPDATE) {
            for (Opportunity o : newList) {
                Opportunity prior = oldMap.get(o.Id);
                if (o.AccountId != prior.AccountId
                    || o.IsClosed != prior.IsClosed
                    || o.Amount != prior.Amount) {
                    addId(accountIds, o.AccountId);
                    addId(accountIds, prior.AccountId);
                }
            }
        }

        if (!accountIds.isEmpty()) {
            recalculate(accountIds);
        }
    }

    private static void addId(Set<Id> ids, Id accountId) {
        if (accountId != null) {
            ids.add(accountId);
        }
    }

    /**
     * Recomputes the totals from the database (so it is correct after any number of DML
     * statements in one transaction) and only updates accounts whose values really change.
     * AccountTrigger updates open opportunities on every account update, which fires the
     * opportunity trigger again; that update changes neither amount, stage nor account,
     * so nothing is recalculated and the two triggers do not loop.
     */
    private static void recalculate(Set<Id> accountIds) {
        Integer pipelineScale = Schema.SObjectType.Account.fields.FB_Open_Pipeline__c.getScale();
        Integer countScale = Schema.SObjectType.Account.fields.FB_Open_Opportunities__c.getScale();

        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Decimal> countByAccount = new Map<Id, Decimal>();
        for (Id accountId : accountIds) {
            pipelineByAccount.put(accountId, 0);
            countByAccount.put(accountId, 0);
        }

        for (AggregateResult ar : [
            SELECT AccountId acc, SUM(Amount) total, COUNT(Id) cnt
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) ar.get('acc');
            Object totalObj = ar.get('total');
            Object cntObj = ar.get('cnt');
            Decimal total = totalObj == null ? 0 : Decimal.valueOf(String.valueOf(totalObj));
            Decimal cnt = cntObj == null ? 0 : Decimal.valueOf(String.valueOf(cntObj));
            pipelineByAccount.put(accountId, total);
            countByAccount.put(accountId, cnt);
        }

        List<Account> toUpdate = new List<Account>();
        for (Account a : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal newPipeline = pipelineByAccount.get(a.Id).setScale(pipelineScale);
            Decimal newCount = countByAccount.get(a.Id).setScale(countScale);

            Boolean changed = a.FB_Open_Pipeline__c == null
                || a.FB_Open_Opportunities__c == null
                || a.FB_Open_Pipeline__c != newPipeline
                || a.FB_Open_Opportunities__c != newCount;

            if (changed) {
                toUpdate.add(new Account(
                    Id = a.Id,
                    FB_Open_Pipeline__c = newPipeline,
                    FB_Open_Opportunities__c = newCount
                ));
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
