    }

    // Run the validation early so a bad record is rejected before it is saved
    public override void onBeforeInsert()
    {
        onValidate();
    }

    public override void onBeforeUpdate(Map<Id, SObject> existingRecords)
    {
        onValidate(existingRecords);
    }

    // Insert validation hook
    public override void onValidate()
    {
        for (SObject record : Records)
        {
            validateAmountNotNegative((Opportunity) record);
        }
    }

    // Update validation hook
    public override void onValidate(Map<Id, SObject> existingRecords)
    {
        for (SObject record : Records)
        {
            Opportunity opp = (Opportunity) record;

            validateAmountNotNegative(opp);

            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);
            if (oldOpp != null
                && oldOpp.StageName == CLOSED_WON
                && opp.Amount != oldOpp.Amount)
            {
                error(WON_AMOUNT_CHANGE_MSG, opp, Opportunity.Amount);
            }
        }
    }

    private void validateAmountNotNegative(Opportunity opp)
